INSERT INTO "public"."RequirementQuestion" ("id", "requirementId", "prompt", "orderIndex", "isMandatory", "expectedAnswer", "gradingRubric", "difficulty") VALUES ('cmo7d3jx700027vpgqchxujju', 'cmo7d3jx700017vpgqt51qily', 'Tell us about your background and how it maps to this role.', 0, true, null, null, 'medium'), ('cmo8928t90002p70kgntismc2', 'cmo8928t90001p70kfcgvknw1', 'What is your current location?', 0, true, null, null, 'medium'), ('cmo8928t90003p70kkayh0jmh', 'cmo8928t90001p70kfcgvknw1', '2- What is your work authorization?', 1, true, null, null, 'medium'), ('cmo8928t90004p70kyz4320ew', 'cmo8928t90001p70kfcgvknw1', '3- Are you open for a Hybrid role in USA with an in-person interview in final round?', 2, true, null, null, 'medium'), ('cmo8928t90005p70k3hx6ix7q', 'cmo8928t90001p70kfcgvknw1', '4- What is your current project all about?', 3, true, null, null, 'medium'), ('cmo8928t90006p70k45fg6bvj', 'cmo8928t90001p70kfcgvknw1', '5- What was your first project all about?', 4, true, null, null, 'medium'), ('cmo8928t90007p70k08h9nplb', 'cmo8928t90001p70kfcgvknw1', '6- Ask questions related to specific skills mentioned in the JD.', 5, true, null, null, 'medium'), ('cmo8928t90008p70kgcxb3j08', 'cmo8928t90001p70kfcgvknw1', '7- Check for domain knowledge', 6, true, null, null, 'medium'), ('cmo89rfnv000bp70k3ei379i1', 'cmo89rfns000ap70kvdiw93yw', 'Tell me about a time you drove a project without authority?', 0, true, null, null, 'medium'), ('cmo89rfnv000cp70kvso4x3fi', 'cmo89rfns000ap70kvdiw93yw', 'How would you reconcile inconsistent data from multiple sources to build a market model?', 1, true, null, null, 'medium'), ('cmo89rfnv000dp70k7jglfqpv', 'cmo89rfns000ap70kvdiw93yw', 'How would you drive adoption of an AI tool among resistant sales teams?', 2, true, null, null, 'medium'), ('cmo89rfnv000ep70kx1xpt8k9', 'cmo89rfns000ap70kvdiw93yw', 'Describe a time your analysis influenced a strategic decision.', 3, true, null, null, 'medium'), ('cmo89rfnv000fp70k8x88obji', 'cmo89rfns000ap70kvdiw93yw', 'Have you ever built a single source of truth? How did you ensure accuracy and adoption?', 4, true, null, null, 'medium'), ('cmodwcn1l0002r40k36262xzc', 'cmodwcn1l0001r40k9i3fdrpg', 'How do you price an AMC contract?', 0, true, null, null, 'medium'), ('cmodwcn1l0003r40ksptqcx2e', 'cmodwcn1l0001r40k9i3fdrpg', 'What factors do you consider while preparing a service proposal for a corporate client?', 1, true, null, null, 'medium'), ('cmodwcn1l0004r40ka9x05ms8', 'cmodwcn1l0001r40k9i3fdrpg', 'How do you calculate profitability for a long-term service contract?', 2, true, null, null, 'medium'), ('cmodwcn1l0005r40k6lqnw882', 'cmodwcn1l0001r40k9i3fdrpg', 'What KPIs would you track for service delivery performance?', 3, true, null, null, 'medium'), ('cmodwcn1l0006r40kb3etc2qm', 'cmodwcn1l0001r40k9i3fdrpg', 'How do you assess service requirements during a site visit?', 4, true, null, null, 'medium'), ('cmomxr8y40002n20ksnd74ld5', 'cmomxr8y40001n20kfn4l0tmu', '"Walk me through your recruiting experience in the last 2-3 years. How much of it has been focused on technical roles (software engineering, data, DevOps, etc.)?"', 0, true, null, null, 'medium'), ('cmomxr8y40003n20kg316qore', 'cmomxr8y40001n20kfn4l0tmu', '"Tell me about your favorite sourcing strategies for hard-to-fill tech roles. Which tools or platforms do you use most, and can you give me an example of a tough role you successfully sourced?"', 1, true, null, null, 'medium'), ('cmomxr8y40004n20kzdchdlic', 'cmomxr8y40001n20kfn4l0tmu', '"How do you evaluate a software engineer’s technical skills during the initial screening stage? What questions or methods do you typically use?"', 2, true, null, null, 'medium'), ('cmomxr8y40005n20kmyxuh530', 'cmomxr8y40001n20kfn4l0tmu', '"Tell me about a time you had to push back on a hiring manager or influence them on a candidate. What was the situation and outcome?"', 3, true, null, null, 'medium'), ('cmomxr8y40006n20kqe830im6', 'cmomxr8y40001n20kfn4l0tmu', '"What recruiting metrics do you track personally? Which ones do you think matter most for technical recruiting?"', 4, true, null, null, 'medium'), ('cmomxr8y40007n20kjfvwvdjp', 'cmomxr8y40001n20kfn4l0tmu', '"Why do you enjoy technical recruiting, and what are you looking for in your next role?"', 5, true, null, null, 'medium'), ('cmomxsp5f000an20kk6xf7egr', 'cmomxsp5f0009n20k86ad5r8y', '"Walk me through your recruiting experience in the last 2-3 years. How much of it has been focused on technical roles (software engineering, data, DevOps, etc.)?"', 0, true, null, null, 'medium'), ('cmomxsp5f000bn20k0df1inok', 'cmomxsp5f0009n20k86ad5r8y', '"Tell me about your favorite sourcing strategies for hard-to-fill tech roles. Which tools or platforms do you use most, and can you give me an example of a tough role you successfully sourced?"', 1, true, null, null, 'medium'), ('cmomxsp5f000cn20kpzia377s', 'cmomxsp5f0009n20k86ad5r8y', '"How do you evaluate a software engineer’s technical skills during the initial screening stage? What questions or methods do you typically use?"', 2, true, null, null, 'medium'), ('cmomxsp5f000dn20kgsadqw58', 'cmomxsp5f0009n20k86ad5r8y', '"Tell me about a time you had to push back on a hiring manager or influence them on a candidate. What was the situation and outcome?"', 3, true, null, null, 'medium'), ('cmomxsp5f000en20k09q6aq4w', 'cmomxsp5f0009n20k86ad5r8y', '"What recruiting metrics do you track personally? Which ones do you think matter most for technical recruiting?"', 4, true, null, null, 'medium'), ('cmomxsp5f000fn20k93bsjd6l', 'cmomxsp5f0009n20k86ad5r8y', '"Why do you enjoy technical recruiting, and what are you looking for in your next role?"', 5, true, null, null, 'medium'), ('cmovvkvs1007nn20k4jzn9f2k', 'cmovvkvs1007mn20kp0o7h93s', 'Give me your professional background, snapshot of technologies and domain experience.', 0, true, null, null, 'medium'), ('cmox26yqv00ayn20kv06jg7ui', 'cmox26yqv00axn20kla7xqwyv', 'Tell us about your background and how it maps to this role.', 0, true, null, null, 'medium'), ('cmox2kuo200b1n20knzj3i169', 'cmox2kuo200b0n20kl1te5gn9', 'Tell us about your background and how it maps to this role.', 0, true, null, null, 'medium'), ('cmox2ll3n00b4n20koes0lmm4', 'cmox2ll3m00b3n20kacr1qrtr', 'Tell us about your background and how it maps to this role.', 0, true, null, null, 'medium'), ('cmp48t76g00d6n20k73irt8wg', 'cmp48t76g00d5n20kthum2jby', 'Tell us about your background and how it maps to this role.', 0, true, null, null, 'medium'), ('cmp48z9kv00d9n20k0r2okf3h', 'cmp48z9kv00d8n20kr9jlukfo', 'Tell us about your background and how it maps to this role.', 0, true, null, null, 'medium'), ('cmp491nv700dcn20k06kvk291', 'cmp491nv700dbn20kdwlj2kmm', 'Tell us about your background and how it maps to this role.', 0, true, null, null, 'medium'), ('cmp5tfzh30021nw0kv6vif7t8', 'cmp5tfzh30020nw0kr6vokxd3', 'What complex ETL workflow did you build using Python and Airflow?', 0, true, null, null, 'medium'), ('cmp5tfzh30022nw0kbyqv7ynq', 'cmp5tfzh30020nw0kr6vokxd3', 'How did you troubleshoot a failing production data pipeline?', 1, true, null, null, 'medium'), ('cmp5tfzh30023nw0kktqx320s', 'cmp5tfzh30020nw0kr6vokxd3', 'What Snowflake query optimization improved performance significantly?', 2, true, null, null, 'medium'), ('cmp5tfzh30024nw0k3k98u3ob', 'cmp5tfzh30020nw0kr6vokxd3', 'How have you handled real-time data ingestion in production?', 3, true, null, null, 'medium'), ('cmp5tfzh30025nw0k8a1l39kg', 'cmp5tfzh30020nw0kr6vokxd3', 'What Salesforce data integrations have you worked on directly?', 4, true, null, null, 'medium'), ('cmp5tfzh30026nw0kja3huxl4', 'cmp5tfzh30020nw0kr6vokxd3', 'How did you implement data quality checks in your pipelines?', 5, true, null, null, 'medium'), ('cmp5tfzh30027nw0kio2s2ec8', 'cmp5tfzh30020nw0kr6vokxd3', 'What challenges did you face while working with MuleSoft integrations?', 6, true, null, null, 'medium'), ('cmp5udmxa003tnw0k9f0pcvij', 'cmp5udmxa003snw0k76ja